PRAGMA foreign_keys=ON;
CREATE TABLE message_channels(code TEXT PRIMARY KEY,name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,production_ready INTEGER NOT NULL DEFAULT 0);
CREATE TABLE message_templates(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,channel TEXT NOT NULL,template_key TEXT NOT NULL,subject TEXT,content TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',UNIQUE(merchant_id,channel,template_key));
CREATE TABLE message_threads(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,customer_id TEXT,channel TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE message_messages(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,thread_id TEXT REFERENCES message_threads(id),direction TEXT NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notification_jobs(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,channel TEXT NOT NULL,template_id TEXT,recipient_hash TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',scheduled_at TEXT,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,idempotency_key));
CREATE TABLE notification_deliveries(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES notification_jobs(id),provider_reference TEXT,status TEXT NOT NULL,attempt_no INTEGER NOT NULL,error_code TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE commerce_events(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,event_type TEXT NOT NULL,session_id TEXT,customer_id TEXT,anonymous_id_hash TEXT,page_path TEXT,entity_type TEXT,entity_id TEXT,idempotency_key TEXT NOT NULL,occurred_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,idempotency_key));
CREATE TABLE commerce_event_properties(event_id TEXT NOT NULL REFERENCES commerce_events(id),property_key TEXT NOT NULL,property_value TEXT NOT NULL,PRIMARY KEY(event_id,property_key));
CREATE TABLE analytics_sessions(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,anonymous_id_hash TEXT,customer_id TEXT,source TEXT,device_type TEXT,started_at TEXT NOT NULL,ended_at TEXT);
CREATE TABLE analytics_page_views(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,session_id TEXT NOT NULL,page_path TEXT NOT NULL,scroll_depth INTEGER NOT NULL DEFAULT 0,duration_ms INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE analytics_daily_metrics(merchant_id TEXT NOT NULL,metric_date TEXT NOT NULL,metric_key TEXT NOT NULL,metric_value REAL NOT NULL,PRIMARY KEY(merchant_id,metric_date,metric_key));
CREATE TABLE analytics_experiments(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',starts_at TEXT,ends_at TEXT,success_event TEXT NOT NULL,auto_winner INTEGER NOT NULL DEFAULT 0);
CREATE TABLE analytics_experiment_variants(id TEXT PRIMARY KEY,experiment_id TEXT NOT NULL REFERENCES analytics_experiments(id),code TEXT NOT NULL,weight INTEGER NOT NULL,content_json TEXT NOT NULL,UNIQUE(experiment_id,code));
CREATE TABLE analytics_experiment_results(experiment_id TEXT NOT NULL,variant_id TEXT NOT NULL,views INTEGER NOT NULL DEFAULT 0,conversions INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(experiment_id,variant_id));
CREATE TABLE merchant_tracking_integrations(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,provider TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,production_ready INTEGER NOT NULL DEFAULT 0,public_config_json TEXT NOT NULL DEFAULT '{}',encrypted_config TEXT,consent_required INTEGER NOT NULL DEFAULT 1,UNIQUE(merchant_id,provider));
